/// <summary>
/// Выполняет асинхронное действие с повторными попытками в случае возникновения ошибки HTTP.
/// </summary>
/// <param name="action">Асинхронная функция, возвращающая целое число.</param>
/// <param name="attempts">Количество попыток выполнения действия.</param>
/// <returns>Результат выполнения действия.</returns>
/// <exception cref="InvalidOperationException">
/// Бросается, если все попытки исчерпаны и действие не удалось выполнить.
/// </exception>
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Цикл для выполнения действия с заданным количеством попыток
    for (var i = 0; i < attempts; i++)
    {
        try
        {
            // Пытаемся выполнить действие и вернуть результат
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        {
            // Если произошла ошибка HTTP и это не последняя попытка:
            // Ожидаем паузу с экспоненциальным увеличением времени ожидания
            // (200 мс * 2^i), чтобы дать системе время на восстановление
            await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, i)));
        }
    }
    // Если все попытки исчерпаны и действие не удалось выполнить,
    // бросаем исключение, указывающее на недостижимость этого состояния
    throw new InvalidOperationException("unreachable");
}
