// Функция worker представляет собой функцию-обработчик (воркер),
// которая читает задачи из канала jobs, обрабатывает их и отправляет результаты в канал results.
// Параметр wg — указатель на WaitGroup, который используется для синхронизации завершения всех воркеров.
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
    // defer wg.Done() гарантирует, что после завершения работы воркера
    // будет вызван метод Done() на WaitGroup, что уменьшит счетчик на 1.
    // Это необходимо для корректного ожидания завершения всех воркеров в main или другой функции.
    defer wg.Done()

    // Цикл for range jobs читает задачи из канала jobs до тех пор, пока канал не будет закрыт.
    // Каждый элемент канала (задача) присваивается переменной j.
    for j := range jobs {
        // Вызываем функцию process для обработки текущей задачи j.
        // Функция возвращает результат r и возможную ошибку err.
        r, err := process(j)

        // Если при обработке задачи произошла ошибка:
        if err != nil {
            // Логируем ошибку с указанием идентификатора задачи (j.ID) и текстом ошибки.
            log.Printf("job %d: %v", j.ID, err)
            // Пропускаем эту задачу и переходим к следующей, не отправляя результат.
            continue
        }

        // Если ошибок нет, отправляем результат r в канал results.
        // Оператор <- блокирует выполнение до тех пор, пока результат не будет принят другим горутин.
        results <- r
    }
}
