 * Дебаунс откладывает выполнение функции до тех пор, пока не прекратятся вызовы
 * в течение заданного времени (ms).
 *
 * @param fn - Функция, которую нужно обернуть.
 * @param ms - Задержка в миллисекундах, после которой функция будет выполнена.
 * @returns Обёрнутая функция с типизированными аргументами исходной функции.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера.
  // Используется для отмены предыдущего таймера при новом вызове.
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, которая принимает те же аргументы, что и исходная.
  return (...args: Parameters<T>) => {
    // Если таймер уже установлен, отменяем его.
    // Это позволяет "сбросить" отсчёт времени при каждом новом вызове.
    if (t) clearTimeout(t);

    // Устанавливаем новый таймер, который вызовет исходную функцию
    // через ms миллисекунд с переданными аргументами.
    t = setTimeout(() => fn(...args), ms);
  };
}
```

